params.data_query:
{# These placeholders are automatically set by the dashboard filters #}
{# See: https://cerb.ai/docs/dashboards/#prompts #}
type:worklist.subtotals
of:ticket
by.count:[created@{{input_date_subtotal_by}},group~10]
query:(
  created:"{{input_date_range}}"
  {% if input_groups %}
  group.id:[{{input_groups}}]
  {% endif %}
  {% if input_statuses %}
  status:[{{input_statuses|join(',')}}]
  {% endif %}
)
format:timeseries
